import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.NkeMC67b.js";const u=JSON.parse('{"title":"Shortcodes","description":"The three Sikshya shortcodes — sikshya_courses, sikshya_login, sikshya_registration — with attributes, defaults, and copy-paste examples.","frontmatter":{"title":"Shortcodes","description":"The three Sikshya shortcodes — sikshya_courses, sikshya_login, sikshya_registration — with attributes, defaults, and copy-paste examples."},"headers":[],"relativePath":"shortcodes.md","filePath":"shortcodes.md","lastUpdated":1778327862000}'),i={name:"shortcodes.md"};function n(d,t,r,c,l,p){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="shortcodes" tabindex="-1">Shortcodes <a class="header-anchor" href="#shortcodes" aria-label="Permalink to &quot;Shortcodes&quot;">​</a></h1><p>Sikshya registers three frontend shortcodes. Drop them into any page, post, widget, or Shortcode block (Gutenberg). Attribute names are lowercase. Defaults below come from the plugin source.</p><h2 id="sikshya-courses" tabindex="-1"><code>[sikshya_courses]</code> <a class="header-anchor" href="#sikshya-courses" aria-label="Permalink to &quot;\`[sikshya_courses]\`&quot;">​</a></h2><p>Renders a grid or list of published courses using the same course-card design as the public catalog. Useful when you want a curated catalog on a landing page or sales funnel.</p><h3 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Attribute</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>per_page</code></td><td><code>9</code></td><td>Min <code>1</code>, max <code>50</code>.</td></tr><tr><td><code>columns</code></td><td>(auto)</td><td><code>3</code> forces a 3-column grid; positive values up to <code>6</code>; <code>0</code> or omitted = auto layout.</td></tr><tr><td><code>view</code></td><td><code>grid</code></td><td><code>grid</code> or <code>list</code>.</td></tr><tr><td><code>category</code></td><td>—</td><td>Slug of a course category (not numeric ID).</td></tr><tr><td><code>tag</code></td><td>—</td><td>Slug of a course tag.</td></tr><tr><td><code>search</code></td><td>—</td><td>Free-text search.</td></tr><tr><td><code>orderby</code></td><td><code>date</code></td><td><code>date</code>, <code>title</code>, or <code>price</code>.</td></tr><tr><td><code>order</code></td><td><code>desc</code></td><td><code>asc</code> or <code>desc</code>.</td></tr><tr><td><code>pagination</code></td><td><code>1</code></td><td><code>1</code> shows pagination; <code>0</code> is single page. Pagination uses <code>sikshya_courses_page</code>.</td></tr></tbody></table><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p>A simple grid:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[sikshya_courses]</span></span></code></pre></div><p>A specific category, sorted by price:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[sikshya_courses per_page=&quot;12&quot; view=&quot;grid&quot; category=&quot;web-design&quot; orderby=&quot;price&quot; order=&quot;asc&quot; pagination=&quot;1&quot;]</span></span></code></pre></div><p>Six bestsellers on a homepage:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[sikshya_courses per_page=&quot;6&quot; columns=&quot;3&quot; orderby=&quot;title&quot; order=&quot;asc&quot; pagination=&quot;0&quot;]</span></span></code></pre></div><h2 id="sikshya-login" tabindex="-1"><code>[sikshya_login]</code> <a class="header-anchor" href="#sikshya-login" aria-label="Permalink to &quot;\`[sikshya_login]\`&quot;">​</a></h2><p>Renders an email-or-username + password sign-in form. Failed logins stay on the same page (no redirect to <code>wp-login.php</code>). Used inside the virtual <code>/login/</code> page and on the checkout step when guests need to sign in.</p><h3 id="attributes-1" tabindex="-1">Attributes <a class="header-anchor" href="#attributes-1" aria-label="Permalink to &quot;Attributes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Attribute</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>redirect_to</code></td><td>(auto)</td><td>Absolute or relative URL after successful login. Falls back to referrer then home.</td></tr></tbody></table><h3 id="examples-1" tabindex="-1">Examples <a class="header-anchor" href="#examples-1" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[sikshya_login]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[sikshya_login redirect_to=&quot;/my-learning/&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[sikshya_login redirect_to=&quot;https://example.com/checkout/&quot;]</span></span></code></pre></div><h2 id="sikshya-registration" tabindex="-1"><code>[sikshya_registration]</code> <a class="header-anchor" href="#sikshya-registration" aria-label="Permalink to &quot;\`[sikshya_registration]\`&quot;">​</a></h2><p>Creates a Sikshya <strong>student</strong> account. Triggers WordPress&#39;s standard new-user emails (admin + user).</p><h3 id="attributes-2" tabindex="-1">Attributes <a class="header-anchor" href="#attributes-2" aria-label="Permalink to &quot;Attributes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Attribute</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>student</code></td><td><code>student</code> or <code>instructor</code>. <strong><code>instructor</code> does not assign the instructor role</strong> — it records a pending application that an admin must approve.</td></tr><tr><td><code>redirect_to</code></td><td>(auto)</td><td>Same behavior as <code>[sikshya_login]</code>.</td></tr></tbody></table><h3 id="examples-2" tabindex="-1">Examples <a class="header-anchor" href="#examples-2" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[sikshya_registration]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[sikshya_registration type=&quot;student&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[sikshya_registration type=&quot;instructor&quot; redirect_to=&quot;/courses/&quot;]</span></span></code></pre></div><h2 id="combining-the-auth-shortcodes" tabindex="-1">Combining the auth shortcodes <a class="header-anchor" href="#combining-the-auth-shortcodes" aria-label="Permalink to &quot;Combining the auth shortcodes&quot;">​</a></h2><p>A two-column &quot;Sign in or join us&quot; page:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;div class=&quot;row&quot;&gt;</span></span>
<span class="line"><span>  &lt;div class=&quot;col&quot;&gt;</span></span>
<span class="line"><span>    &lt;h2&gt;Sign in&lt;/h2&gt;</span></span>
<span class="line"><span>    [sikshya_login redirect_to=&quot;/my-learning/&quot;]</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>  &lt;div class=&quot;col&quot;&gt;</span></span>
<span class="line"><span>    &lt;h2&gt;Create an account&lt;/h2&gt;</span></span>
<span class="line"><span>    [sikshya_registration redirect_to=&quot;/my-learning/&quot;]</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>&lt;/div&gt;</span></span></code></pre></div><h2 id="block-editor-gutenberg" tabindex="-1">Block editor (Gutenberg) <a class="header-anchor" href="#block-editor-gutenberg" aria-label="Permalink to &quot;Block editor (Gutenberg)&quot;">​</a></h2><p>Sikshya doesn&#39;t (yet) ship a custom block. Use the WordPress <strong>Shortcode block</strong> to wrap any of the three shortcodes above. For richer page-builder integration, see <a href="/plugins/sikshya/elementor-integration">Blocks &amp; page builders</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/plugins/sikshya/elementor-integration">Blocks &amp; page builders</a> — how Sikshya works with Elementor, Divi, Bricks.</li><li><a href="/plugins/sikshya/learners">Learners</a> — what happens after registration / login.</li></ul>`,32)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
